const item = $input.first();
let content = '';
if (item.binary?.data?.data) {
  content = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else if (typeof item.json?.data === 'string') {
  content = item.json.data;
}
return [{ json: { stdout: content } }];

function getHtmlBody(nodeName) {
  const items = $node[nodeName].all();
  if (!items.length) return '';
  const j = items[0].json;
  return j.data || j.body || '';
}

function parseTipsHtml(html) {
  const items = [];
  const seen = new Set();
  const alts = [...html.matchAll(/alt="([^"]{10,120})"/g)].map(m => m[1]);
  const links = [...html.matchAll(/href="(https:\/\/tips\.jp\/u\/[^"]+\/a\/[^"]+)"/g)].map(m => m[1]);
  for (let i = 0; i < links.length && items.length < 10; i++) {
    const url = links[i];
    if (seen.has(url)) continue;
    seen.add(url);
    const title = alts[i] || url.split('/').pop();
    if (/Tips.*記事|カテゴリー/.test(title)) continue;
    items.push({ title, url, description: 'Tips検索結果' });
  }
  return items;
}

function parseBrainHtml(html) {
  const items = [];
  const seen = new Set();
  const links = [...html.matchAll(/href="(\/u\/[^"]+\/a\/[^"]+)"/g)].map(m => `https://brain-market.com${m[1]}`);
  for (const url of links) {
    if (seen.has(url)) continue;
    seen.add(url);
    const slug = url.split('/').pop();
    items.push({ title: `Brain教材 (${slug})`, url, price: '未詳', description: 'Brain検索結果' });
    if (items.length >= 10) break;
  }
  return items;
}

let combinedText = '=== 【超短期トレンド分析用マルチソースデータ】 ===\n\n';

// --- 1. X (Twitter) ---
try {
  let xOutput = $node['Execute Command'].all()[0]?.json?.stdout;
  if (!xOutput) xOutput = $node['Normalize Mock X'].all()[0]?.json?.stdout;
  if (xOutput) {
    const parsed = JSON.parse(xOutput);
    const tweets = Array.isArray(parsed) ? parsed : (parsed.data || []);
    combinedText += '■ [X (Twitter) の言及・バズ] ---------\n';
    let count = 0;
    for (const t of tweets) {
      const text = t.text || '';
      if (text && !text.includes('公式LINE') && !text.includes('プレゼント企画') && !text.includes('プロフをチェック')) {
        const createdAt = t.createdAtISO || t.created_at || '不明';
        const likes = t.metrics?.likes ?? t.favorite_count ?? 0;
        const rts = t.metrics?.retweets ?? t.retweet_count ?? 0;
        combinedText += `- [${createdAt}] Fav:${likes} / RT:${rts}\n  内容: ${text.replace(/\n/g, ' ')}\n`;
        count++;
      }
      if (count >= 50) break;
    }
    combinedText += '\n';
  }
} catch (e) {
  combinedText += `※ Xデータのパースエラー: ${e.message}\n\n`;
}

// --- 2. note ---
try {
  const noteItems = [
    ...$node['RSS Read (note-AI副業)'].all(),
    ...$node['RSS Read (note-AIツール)'].all()
  ];
  if (noteItems.length > 0) {
    combinedText += '■ [noteの新着・トレンド記事] ---------\n';
    for (const item of noteItems.slice(0, 15)) {
      combinedText += `- タイトル: ${item.json.title}\n  概要: ${item.json.contentSnippet || 'なし'}\n  URL: ${item.json.link}\n`;
    }
    combinedText += '\n';
  }
} catch (e) {
  combinedText += `※ noteデータ取得エラー: ${e.message}\n\n`;
}

// --- 3. Brain ---
try {
  const brainHtml = getHtmlBody('HTTP Request (Brain)');
  const brainItems = brainHtml ? parseBrainHtml(brainHtml) : [];
  if (brainItems.length > 0) {
    combinedText += '■ [Brain 実売商品・教材] ---------\n';
    for (const item of brainItems) {
      combinedText += `- 教材名: ${item.title}\n  価格: ${item.price}円\n  URL: ${item.url}\n`;
    }
    combinedText += '\n';
  }
} catch (e) {
  combinedText += `※ Brainデータエラー: ${e.message}\n\n`;
}

// --- 4. Tips ---
try {
  const tipsHtml = getHtmlBody('HTTP Request (Tips)');
  const tipsItems = tipsHtml ? parseTipsHtml(tipsHtml) : [];
  if (tipsItems.length > 0) {
    combinedText += '■ [Tips 副業ノウハウ教材] ---------\n';
    for (const item of tipsItems) {
      combinedText += `- 教材名: ${item.title}\n  URL: ${item.url}\n`;
    }
    combinedText += '\n';
  }
} catch (e) {
  combinedText += `※ Tipsデータエラー: ${e.message}\n\n`;
}

// --- 5. Qiita ---
try {
  const qiitaItems = $node['HTTP Request (Qiita)'].all();
  if (qiitaItems.length > 0) {
    combinedText += '■ [Qiita 技術実装・エラー解決] ---------\n';
    for (const item of qiitaItems.slice(0, 15)) {
      combinedText += `- 記事名: ${item.json.title}\n  LG数: ${item.json.likes_count || 0}\n  タグ: ${(item.json.tags || []).map(t => t.name).join(', ')}\n  URL: ${item.json.url}\n`;
    }
    combinedText += '\n';
  }
} catch (e) {
  combinedText += `※ Qiitaデータエラー: ${e.message}\n\n`;
}

return [{ json: { textData: combinedText } }];

